SELECT r.id, r.refund_no, r.fee_record_id, r.eir_id, r.company_id, r.amount, r.status, r.applicant, r.applied_at, r.approver, r.approved_at, r.reject_reason, r.remark, r.create_time, e.eir_no AS eirNo, c.name AS companyName FROM refund_record r LEFT JOIN eir_order e ON e.id = r.eir_id LEFT JOIN transport_company c ON c.id = r.company_id
AND r.status = #{status}
AND r.company_id = #{companyId}
ORDER BY r.id DESC LIMIT #{offset}, #{size}

SELECT COUNT(1) FROM refund_record r


        AND r.status = #{status}


        AND r.company_id = #{companyId}
